 let b=j["boolean"]==true;let traced=true;assert_eq!(s["boolean_routes"],if b{json!([0,rounds,0,0])}else{json!([0,0,0,0])});let mut last=0;let mut metrics=BTreeMap::<&str,Vec<f64>>::new();let mut fused=0;
